<?php
declare(strict_types=1);

/*
    filename: install_pick_reminder_dashboard_v001_20260906_024247am.php
    VERSION: v001
    LAST MODIFIED: 9/6/2026 2:42:47 am

    PURPOSE:
    - Install the MRL Pick Reminder Dashboard v001.
    - Add TEST/LIVE recipient scopes, MANUAL/AUTO/OFF modes, configurable reminder offsets,
      editable message templates, manual sending, send history, scheduler state, and auto duplicate protection.
    - Patch cron_all_schedulers.php v001 -> v002 so the reminder scheduler is checked every minute.
    - Default safely to MANUAL + TEST (MRL Test Team / userID 999 only).

    CREATES:
    - /public_html/pick_reminder_dashboard.php
    - /public_html/pick_reminder_helper.php
    - /public_html/pick_reminder_scheduler.php

    MODIFIES:
    - /public_html/cron_all_schedulers.php v001 -> v002

    RUNTIME STATE:
    - /public_html/_pick_reminder/config.json
    - /public_html/_pick_reminder/send_log.jsonl
    - /public_html/_pick_reminder/scheduler_state.json

    SAFETY:
    - Admin-only dashboard.
    - Existing target filenames block installation.
    - Exact current cron v001 anchors are required.
    - Rollback copy of cron_all_schedulers.php is created before Apply.
    - LIVE AUTO requires typed ENABLE LIVE AUTO.
    - LIVE manual sends require typed SEND LIVE.
    - Every send rechecks current pick state immediately before email.
*/

date_default_timezone_set('America/New_York');
if (session_status()===PHP_SESSION_NONE) session_start();

$root=rtrim((string)($_SERVER['DOCUMENT_ROOT']??__DIR__),'/\\');
$cron=$root.DIRECTORY_SEPARATOR.'cron_all_schedulers.php';
$targets=[
    'pick_reminder_dashboard.php'=>'',
    'pick_reminder_helper.php'=>'',
    'pick_reminder_scheduler.php'=>'',
];

$backupDir=$root.DIRECTORY_SEPARATOR.'_migration_backups'.DIRECTORY_SEPARATOR.'pick_reminder_dashboard_v001_20260906_024247am';
$cronBackup=$backupDir.DIRECTORY_SEPARATOR.'cron_all_schedulers.php';

function iprd_h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function iprd_decode(string $b64):string{$d=base64_decode($b64,true);return is_string($d)?$d:'';}
function iprd_write_atomic(string $path,string $content):array{
    try{$s=bin2hex(random_bytes(4));}catch(Throwable $e){$s=(string)mt_rand(100000,999999);}
    $tmp=$path.'.tmp_'.$s;
    if(@file_put_contents($tmp,$content,LOCK_EX)===false)return [false,'Could not write temporary file: '.$tmp];
    if(!@rename($tmp,$path)){@unlink($tmp);return [false,'Could not replace/create: '.$path];}
    return [true,''];
}
function iprd_syntax(string $path):array{
    $cmd=escapeshellarg(PHP_BINARY?:'php').' -l '.escapeshellarg($path).' 2>&1';$out=[];$code=1;@exec($cmd,$out,$code);
    if($code===0)return [true,implode("\n",$out)];
    if(!$out)return [null,'PHP CLI syntax check unavailable on this host.'];
    return [false,implode("\n",$out)];
}

$cronContent=is_file($cron)?(string)@file_get_contents($cron):'';
$cronExists=is_file($cron);
$cronWritable=$cronExists&&is_writable($cron);
$rootWritable=is_writable($root);
$mailAvailable=function_exists('mail');

$cronVersionOk=strpos($cronContent,'VERSION: v001')!==false
    && strpos($cronContent,"const CAS_VERSION = 'v001';")!==false
    && strpos($cronContent,"const CAS_SIGNATURE = 'CRON_ALL_SCHEDULERS v001';")!==false;

$liveAnchor=<<<'TXT'
    [
        'name' => 'live',
        'script' => $rootDir . '/race_results/cron_master_scheduler.php',
    ],
TXT;
$cronTargetAnchorOk=substr_count($cronContent,$liveAnchor)===1;

$newNamesFree=true;
foreach(array_keys($targets) as $name)if(file_exists($root.DIRECTORY_SEPARATOR.$name)){$newNamesFree=false;break;}

$payloadsOk=true;
foreach($targets as $b64){if(strpos(iprd_decode($b64),'VERSION: v001')===false){$payloadsOk=false;break;}}

$requiredPass=$cronExists&&$cronWritable&&$rootWritable&&$mailAvailable&&$cronVersionOk&&$cronTargetAnchorOk&&$newNamesFree&&$payloadsOk;

$message='';$messageType='';

if(($_POST['action']??'')==='apply'){
    if(!$requiredPass){$message='APPLY BLOCKED — one or more required preflight checks are not passing.';$messageType='err';}
    else{
        if(!is_dir($backupDir)&&!@mkdir($backupDir,0755,true)){$message='APPLY FAILED — could not create rollback directory.';$messageType='err';}
        elseif(!@copy($cron,$cronBackup)){$message='APPLY FAILED — could not back up cron_all_schedulers.php.';$messageType='err';}
        else{
            $created=[];$error='';
            foreach($targets as $name=>$b64){
                $path=$root.DIRECTORY_SEPARATOR.$name;
                [$ok,$err]=iprd_write_atomic($path,iprd_decode($b64));
                if(!$ok){$error=$err;break;}
                $created[]=$path;
                [$syn,$rep]=iprd_syntax($path);
                if($syn===false){$error='PHP syntax check failed for '.$name.': '.$rep;break;}
            }

            if($error===''){
                $updated=$cronContent;
                $updated=str_replace(
                    ' * VERSION: v001'."\n".' * LAST MODIFIED: 5/25/2026 3:26:00 pm',
                    ' * VERSION: v002'."\n".' * LAST MODIFIED: 9/6/2026 2:42:47 am',
                    $updated,$c1
                );
                $updated=str_replace("const CAS_VERSION = 'v001';","const CAS_VERSION = 'v002';",$updated,$c2);
                $updated=str_replace("const CAS_SIGNATURE = 'CRON_ALL_SCHEDULERS v001';","const CAS_SIGNATURE = 'CRON_ALL_SCHEDULERS v002';",$updated,$c3);

                $newLive=$liveAnchor
                    ."    [\n"
                    ."        'name' => 'pick_reminder',\n"
                    ."        'script' => \$rootDir . '/pick_reminder_scheduler.php',\n"
                    ."    ],\n";
                $updated=str_replace($liveAnchor,$newLive,$updated,$c4);

                if(!($c1===1&&$c2===1&&$c3===1&&$c4===1))$error='cron_all_schedulers.php patch anchors did not match exactly.';
                else{
                    [$ok,$err]=iprd_write_atomic($cron,$updated);
                    if(!$ok)$error=$err;
                    else{[$syn,$rep]=iprd_syntax($cron);if($syn===false)$error='Patched cron syntax failed: '.$rep;}
                }
            }

            if($error!==''){
                @copy($cronBackup,$cron);
                foreach($created as $p)@unlink($p);
                $message='APPLY FAILED — '.$error.' Original cron restored and created Pick Reminder files removed.';
                $messageType='err';
            }else{
                $message='INSTALL COMPLETE — Pick Reminder Dashboard v001 installed. It starts in MANUAL + TEST scope, so no automatic live emails are enabled.';
                $messageType='ok';
            }
        }
    }
}

if(($_POST['action']??'')==='rollback'){
    if(!is_file($cronBackup)){$message='ROLLBACK NOT AVAILABLE — no rollback copy exists yet.';$messageType='err';}
    else{
        $ok=@copy($cronBackup,$cron);
        foreach(array_keys($targets) as $name)@unlink($root.DIRECTORY_SEPARATOR.$name);
        if($ok){$message='ROLLBACK COMPLETE — original cron restored and Pick Reminder PHP files removed. Runtime _pick_reminder logs/state were intentionally preserved.';$messageType='ok';}
        else{$message='ROLLBACK FAILED — could not restore cron_all_schedulers.php.';$messageType='err';}
    }
}
