<?php
$checks=[
['cron_all_schedulers.php exists',true,$cronExists,$cron],
['cron_all_schedulers.php writable',true,$cronWritable,'Required to add pick_reminder scheduler target.'],
['Expected cron v001 baseline',true,$cronVersionOk,'Confirms current GitHub VERSION/signature anchors.'],
['Live scheduler target anchor',true,$cronTargetAnchorOk,'Confirms insertion point exists exactly once.'],
['New Pick Reminder filenames unused',true,$newNamesFree,'Prevents overwriting unexpected files.'],
['Embedded PHP payloads valid',true,$payloadsOk,'Three complete v001 target files embedded.'],
