['LIVE safeguards',false,true,'Typed confirmations required for LIVE manual and LIVE AUTO.'],
];
foreach($checks as [$label,$required,$ok,$detail]):?>
<tr><td><?php echo iprd_h($label);?></td><td><?php echo $required?'Required':'Info';?></td><td class="<?php echo $required?($ok?'pass':'fail'):'infoStatus';?>"><?php echo $required?($ok?'PASS':'FAIL'):'INFO';?></td><td><?php echo iprd_h($detail);?></td></tr>
<?php endforeach;?></tbody></table></div>

